\kern-0.1em/\kern-0.15em
\lower0.25ex\hbox{$\scriptstyle 2$}}B} \right]^m}$$
<br><br>$$\therefore$$ $$\,\,\,\,{{Rat{e_2}} \over {Rat{e_1}}} = {{k{{\left[ {2A} \right]}^n}{{\left[ {{\raise0.5ex\hbox{$\scriptstyle 1$}
\kern-0.1em/\kern-0.15em
\lower0.25ex\hbox{$\scriptstyle 2$}}B} \right]}^m}} \over {k{{\left[ A \right]}^n}{{\left[ B \right]}^m}}}$$
<br><br>$$ = {\left[ 2 \right]^n}{\left[ {{\raise0.5ex\hbox{$\scriptstyle 1$}
\kern-0.1em/\kern-0.15em
\lower0.25ex\hbox{$\scriptstyle 2$}}} \right]^m} = {2^n}{.2^{ - m}} = {2^{n - m}}$$

