\begin{aligned}
& I=\int_0^{\frac{\pi}{2}}\left(1+\sin x(-\sin 3 x)+\sin ^2 x-\sin ^3 x \sin 3 x\right) d x \\\\
& 2 I=\int_0^{\frac{\pi}{2}}\left(3+\cos 4 x+\cos ^3 x \cos 3 x-\sin ^3 x \sin 3 x\right) d x \\\\
& 2 I=\int_0^{\frac{\pi}{2}} 3+\cos 4 x+\left(\frac{\cos 3 x+3 \cos x}{4}\right) \cos 3 x-\sin 3 x\left(\frac{3 \sin x-\sin 3 x}{4}\right) d x
\end{aligned}
$$
<br/><br/>$$
\begin{aligned}
& 2 \mathrm{I}=\int_0^{\frac{\pi}{2}}\left(3+\cos 4 \mathrm{x}+\frac{1}{4}+\frac{3}{4} \cos 4 \mathrm{x}\right) \mathrm{dx} \\\\
& 2 \mathrm{I}=\frac{13}{4} \times \frac{\pi}{2}+\frac{7}{4}\left(\frac{\sin 4 \mathrm{x}}{4}\right)_0^{\frac{\pi}{2}} \Rightarrow \mathrm{I}=\frac{13 \pi}{16}
\end{aligned}
$$

Given, $$f_{n}=\int_\limits{0}^{\frac{\pi}{2}}\left(\sum_\limits{k=1}^{n} \sin ^{k-1} x\right)\left(\sum_\limits{k=1}^{n}(2 k-1) \sin ^{k-1} x\right) \cos x d x$$
<br/><br/>$$
\begin{aligned}
& \text { Put } \sin x=t \\\\
& \cos x d x=d t \\\\
& f_n=\int_0^1\left(\sum_{k=1}^n(t)^{k-1}\right)\left(\sum_{k=1}^n(2 k-1)(t)^{k-1}\right) d t
\end{aligned}
$$
<br/><br/>$$ \therefore $$ $$
\begin{aligned}
 f_{21}=\int_0^1\left(\sum_{k=1}^{21}(t)^{20}\right)\left(\sum_{k=1}^{21}(2 k-1)(t)^{20}\right) d t
\end{aligned}
$$
<br/><br/>= $$\int\limits_0^1 {\left( {{t^0} + {t^1} + {t^2} + ...... + {t^{20}}} \right)\left( {1{t^0} + 3{t^1} + 5{t^2} + ...... + 41{t^{20}}} \right)} dt$$
<br/><br/>$$ \therefore $$ $$
\begin{aligned}
 f_{20}=\int_0^1\left(\sum_{k=1}^{20}(t)^{19}\right)\left(\sum_{k=1}^{20}(2 k-1)(t)^{19}\right) d t
\end{aligned}
$$
<br/><br/>= $$\int\limits_0^1 {\left( {{t^0} + {t^1} + {t^2} + ...... + {t^{19}}} \right)\left( {1{t^0} + 3{t^1} + 5{t^2} + ...... + 39{t^{19}}} \right)} dt$$
<br/><br/>Now, $$
f_{21}-f_{20}
$$
<br/><br/>$$
\begin{aligned}
=\int_0^1\left(1+t+t^2+\ldots .\right. & \left.+t^{19}\right)(41) t^{20} \\
& +\left(1+3 t+5 t^2+\ldots . .+41 t^{20}\right) t^{20} d t
\end{aligned}
$$
<br/><br/>$$
\begin{aligned}
& =\left(\frac{1}{21}+\frac{1}{22}+\ldots+\frac{1}{40}\right) 41+\left(\frac{1}{21}+\frac{3}{22}+\ldots . .+\frac{39}{40}+\frac{41}{41}\right) \\\\
& =\left[\frac{42}{21}+\frac{44}{22}+\frac{46}{23}+\ldots .+\frac{80}{40}+\frac{41}{41}\right] \\\\
& =40+1=41
\end{aligned}
$$

question:
Let y = y(x) satisfies the equation $${{dy} \over {dx}} - |A| = 0$$, for all x &gt; 0, where $$A = \left[ {\matrix{
   y &amp; {\sin x} &amp; 1  \cr 
   0 &amp; { - 1} &amp; 1  \cr 
   2 &amp; 0 &amp; {{1 \over x}}  \cr 

 } } \right]$$. If $$y(\pi ) = \pi  + 2$$, then the value of $$y\left( {{\pi  \over 2}} \right)$$ is :

explanation:
$$
\begin{aligned}
& (\cos y)(\ln (\cos y))^2 d x=(1+3 x \ln \cos y) \sin y d y \\\\
& \Rightarrow \frac{d x}{d y}=\frac{(1+3 x \ln \cos y) \sin y}{(\ln \cos y)^2 \cos y} \\\\
& =\tan y\left[\frac{1}{(\ln \cos y)^2}+\frac{3 x}{\ln \cos y}\right] \\\\
& \Rightarrow \frac{d x}{d y}-\left(\frac{3 \tan y}{\ln \cos y}\right) x=\frac{\tan y}{(\ln \cos y)^2}
\end{aligned}
$$
<br/><br/>Which is a linear differential equation.
<br/><br/>$$
\text { I.F. }=e^{-\int \frac{3 \tan y}{\ln \cos y} d y}=(\ln \cos y)^3
$$
<br/><br/>So, the solution is :
<br/><br/>$$
\begin{aligned}
& x \times(\ln \cos y)^3=\int\left((\ln \cos y)^3 \times \frac{\tan y}{(\ln \cos y)^2}\right) d y \\\\
& x \times(\ln \cos y)^3=\frac{-(\ln \cos y)^2}{2}+C
\end{aligned}
$$
<br/><br/>$$
\text { At } y=\frac{\pi}{3} \text {, }
$$
<br/><br/>$$
\begin{aligned}
& \frac{1}{2 \ln 2} \times\left(\ln \left(\frac{1}{2}\right)\right)^3=-\frac{\left(\ln \left(\frac{1}{2}\right)\right)^2}{2}+C \\\\
& \Rightarrow C=0
\end{aligned}
$$
<br/><br/>$$
\begin{aligned}
& \text { So, } x \times \ln ^3 \cos y=\frac{-\ln ^2 \cos y}{2} \\\\
& \text { At } y=\frac{\pi}{6}, x \times\left(\ln \left(\frac{\sqrt{3}}{2}\right)\right)^3=-\frac{1}{2}\left(\ln \left(\frac{\sqrt{3}}{2}\right)\right)^2 \\\\
& \Rightarrow x=-\frac{1}{2 \ln \left(\frac{\sqrt{3}}{2}\right)}
\end{aligned}
$$
<br/><br/>$$
\begin{aligned}
& =-\frac{1}{2[\ln \sqrt{3}-\ln 2]}=\frac{-1}{2\left[\frac{1}{2} \ln 3-\ln 2\right]} \\\\
& =\frac{-1}{2\left[\frac{\ln 3-\ln 4}{2}\right]}=\frac{1}{\ln 4-\ln 3} \\\\
& \Rightarrow m=4, n=3 \\\\
& \Rightarrow m n=12
\end{aligned}
$$

The given differential equation is,
<br/><br/>$$
\begin{aligned}
& (y-2 \log x) d x+\left(x \log x^2\right) d y=0 \\\\
& \Rightarrow \frac{d y}{d x}=\frac{(2 \log x-y)}{2 x \log x} \\\\
& \Rightarrow \frac{d y}{d x}+\frac{y}{2 x \log x}=\frac{1}{x}
\end{aligned}
$$
<br/><br/>It is a linear differential equation.
<br/><br/>$$
\therefore \text { I.F. }=e^{\int \frac{1}{2 x \log x} d x}
$$
<br/><br/>Put $\log x=t \Rightarrow \frac{1}{x} d x=d t$
<br/><br/>$$
\therefore \text { I.F. }=e^{\int \frac{1}{2 t} d t}=e^{\log (t)^{\frac{1}{2}}}=\sqrt{t}=\sqrt{\log x}
$$
<br/><br/>So, required solution is,
<br/><br/>$$
\begin{aligned}
& y \sqrt{\log x}=\int \frac{\sqrt{\log x}}{x} d x \\\\
& \log x=v \Rightarrow \frac{1}{x} d x=d v \\\\
& \Rightarrow y \sqrt{\log x}=\int \sqrt{v} d v+C \\\\
& \Rightarrow y \sqrt{\log x}=\frac{2 v^{3 / 2}}{3}+C \\\\
& \Rightarrow y \sqrt{\log x}=\frac{2}{3}(\log x)^{3 / 2}+C
\end{aligned}
$$
<br/><br/>Now, this curve passes through $\left(e, \frac{4}{3}\right)$ and $\left(e^4, \alpha\right)$
<br/><br/>$$
\begin{aligned}
& \therefore \frac{4}{3} \sqrt{\log e}=\frac{2}{3}(\log e)^{3 / 2}+C \\\\
& \Rightarrow C=\frac{4}{3}-\frac{2}{3}=\frac{2}{3}
\end{aligned}
$$
<br/><br/>Also, $\alpha \sqrt{\log e^4}=\frac{2}{3}\left(\log e^4\right)^{3 / 2}+\frac{2}{3}$
<br/><br/>$$
\begin{aligned}
& \Rightarrow 2 \alpha=\frac{2}{3} \times(4)^{3 / 2}+\frac{2}{3}=\frac{16}{3}+\frac{2}{3}=\frac{18}{3} \\\\
& \Rightarrow \alpha=3
\end{aligned}
$$

Given, differential equation
<br/><br/>$$
\begin{aligned}
& (x \cos x) d y+(x y \sin x+y \cos x-1) d x=0,0 < x < \frac{\pi}{2} \\\\
& \Rightarrow \frac{d y}{d x}+\frac{x y \sin x+y \cos x-1}{x \cos x}=0 \\\\
& \Rightarrow \frac{d y}{d x}+\left(\frac{x y \sin x+y \cos x}{x \cos x}\right)=\frac{1}{x \cos x} \\\\
& \Rightarrow  \frac{d y}{d x}+\left(\tan x+\frac{1}{x}\right) y=\frac{1}{x \cos x}
\end{aligned}
$$
<br/><br/>Which is linear differential equation in the form of
<br/><br/>$$
\begin{aligned}
& \frac{d y}{d x}+P y=Q \\\\
& \therefore \mathrm{IF}=e^{\int\left(\tan x+\frac{1}{x}\right) d x}=e^{(\log \sec x+\log x)}=e^{\log (x \sec x)}=x \sec x
\end{aligned}
$$
<br/><br/>$\therefore$ The general solution of the given differential equation
<br/><br/>$$
\begin{array}{rlrl}
y \cdot \mathrm{IF} =\int(Q \times \mathrm{IF}) d x+c \\\\
\Rightarrow y(x \sec x) =\int\left(\frac{1}{x \cos x} x \sec x\right) d x+c \\\\
\Rightarrow  x y \sec x  =\int \sec ^2 x d x+c \\\\
\Rightarrow  x y \sec x =\tan x+c ........(i)
\end{array}
$$
<br/><br/>Since, $\frac{\pi}{3} y\left(\frac{\pi}{3}\right)=\sqrt{3} \Rightarrow y\left(\frac{\pi}{3}\right)=\frac{3 \sqrt{3}}{\pi}$
<br/><br/>$$
\begin{aligned}
& \therefore \frac{\pi}{3}\left(\frac{3 \sqrt{3}}{\pi}\right) \sec \left(\frac{\pi}{3}\right)=\tan \left(\frac{\pi}{3}\right)+c \\\\
& \Rightarrow \sqrt{3}(2)=\sqrt{3}+c \\\\
& \begin{aligned}
\Rightarrow & c=\sqrt{3}
\end{aligned} 
\end{aligned}
$$
<br/><br/>On putting the value of $c$ in Eq. (i), we get
<br/><br/>$$
\begin{aligned}
&x y \sec x  =\tan x+\sqrt{3} \\\\
&\Rightarrow y =\frac{1}{x}(\sin x+\sqrt{3} \cos x) \\\\
& y^{\prime}  =\frac{1}{x}(\cos x-\sqrt{3} \sin x)-\frac{1}{x^2}(\sin x+\sqrt{3} \cos x)
\end{aligned}
$$
<br/><br/>$\begin{aligned} & \text { and } y^{\prime \prime}=\frac{1}{x}(-\sin x-\sqrt{3} \cos x)-\frac{1}{x^2}(\cos x-\sqrt{3} \sin x)  -\frac{1}{x^2}(\cos x-\sqrt{3} \sin x) \\ & -\frac{2}{x^3}(\cos x-\sqrt{3} \sin x) \\\\ & \therefore\left|\frac{\pi}{6} y^{\prime \prime}\left(\frac{\pi}{6}\right)+2 y^{\prime}\left(\frac{\pi}{6}\right)\right|=|-2|=2 \\\\ & \end{aligned}$

question:
Let y = y(x) be the solution of the differential equation $${{dy} \over {dx}} + 2y = f\left( x \right),$$ <br/><br/>where $$f\left( x \right) = \left\{ {\matrix{
   {1,} &amp; {x \in \left[ {0,1} \right]}  \cr 
   {0,} &amp; {otherwise}  \cr 

 } } \right.$$
<br/><br/>If y(0) = 0, then $$y\left( {{3 \over 2}} \right)$$ is :

explanation:
$\frac{d y}{d x}+\left(\frac{2 x^{2}+11 x+13}{x^{3}+6 x^{2}+11 x+6}\right) y=\frac{(x+3)}{x+1}, x>-1$,

<br/><br/>Integrating factor I.F. $=e^{\int \frac{2 x^{2}+11 x+13}{x^{3}+6 x^{2}+11 x+6} d x}$

<br/><br/>$$
\begin{aligned}
& \text { Let } \frac{2 x^{2}+11 x+13}{(x+1)(x+2)(x+3)}=\frac{A}{x+1}+\frac{B}{x+2}+\frac{C}{x+3} \\\\
& A=2, B=1, C=-1 \\\\
& \text { I.F. }=e^{(2 \ln |x+1|+\ln |x+2|-\ln |x+3|)} \\\\
& =\frac{(x+1)^{2}(x+2)}{x+3}
\end{aligned}
$$

<br/><br/>Solution of differential equation

<br/><br/>$$
\begin{aligned}
&y \cdot \frac{(x+1)^{2}(x+2)}{x+3}=\int(x+1)(x+2) d x \\\\
&y \frac{(x+1)^{2}(x+2)}{x+3}=\frac{x^{3}}{3}+\frac{3 x^{2}}{2}+2 x+c
\end{aligned}
$$

<br/><br/>Curve passes through $(0,1)$

<br/><br/>$$
\begin{gathered}
1 \times \frac{1 \times 2}{3}=0+c \Rightarrow c=\frac{2}{3} \\\\
\text { So, } y(1)=\frac{\frac{1}{3}+\frac{3}{2}+2+\frac{2}{3}}{\frac{\left(2^{2} \times 3\right)}{4}}=\frac{3}{2}
\end{gathered}
$$

We have,
<br/><br/>$$
\begin{aligned}
& \left(1-x^2 y^2\right) d x=y d x+x d y, y(1)=2 \\\\
& d x=\frac{y d x+x d y}{1-(x y)^2}
\end{aligned}
$$
<br/><br/>On integrating both sides, we get
<br/><br/>$$
\begin{aligned}
\int d x & =\int \frac{d(x y)}{1-(x y)^2} \\\\
x & =\frac{1}{2} \log \left|\frac{1+x y}{1-x y}\right|+C
\end{aligned}
$$
<br/><br/>As, $y(1)=2$
<br/><br/>$$
\begin{aligned}
1 & =\frac{1}{2} \log \left|\frac{1+2}{1-2}\right|+C \\\\
\Rightarrow C & =1-\frac{1}{2} \log 3
\end{aligned}
$$
<br/><br/>Now, substitute $x=2$ as $y(2)=\alpha$
<br/><br/>$$
2=\frac{1}{2} \log \left|\frac{1+2 \alpha}{1-2 \alpha}\right|+1-\frac{1}{2} \log 3
$$
<br/><br/>$$
\begin{aligned}
1+\frac{1}{2} \log 3 & =\frac{1}{2} \log \left|\frac{1+2 \alpha}{1-2 \alpha}\right| \\\\
2+\log 3 & =\log \left|\frac{1+2 \alpha}{1-2 \alpha}\right|
\end{aligned}
$$
<br/><br/>$$
\begin{aligned}
&\Rightarrow \frac{1+2 \alpha}{1-2 \alpha} \mid  =3 e^2 \\\\
&\Rightarrow \frac{1+2 \alpha}{1-2 \alpha}= \pm \frac{3 e^2}{1} \\\\
& \Rightarrow\frac{1}{2 \alpha}  =\frac{ \pm 3 e^2+1}{ \pm 3 e^2-1} \\\\
&\Rightarrow 2 \alpha=\frac{ \pm 3 e^2-1}{ \pm 3 e^2+1}
\end{aligned}
$$
<br/><br/>$$
\begin{array}{ll}
\Rightarrow  \alpha=\frac{1}{2}\left(\frac{ \pm 3 e^2-1}{1 \pm 3 e^2}\right) \\\\
\therefore  \alpha=\frac{3 e^2-1}{2\left(1+3 e^2\right)} \text { or } \frac{3 e^2+1}{2\left(3 e^2-1\right)}
\end{array}
$$

question:
If $$f\left( x \right) = \left| {\matrix{
   {\cos x} &amp; x &amp; 1  \cr 
   {2\sin x} &amp; {{x^2}} &amp; {2x}  \cr 
   {\tan x} &amp; x &amp; 1  \cr 

 } } \right|,$$ then $$\mathop {\lim }\limits_{x \to 0} {{f'\left( x \right)} \over x}$$

explanation:
$$f(x)=\frac{\sin x+\cos x-\sqrt{2}}{\sin x-\cos x}$$
<br/><br/>$$
\begin{aligned}
& =\frac{\frac{1}{\sqrt{2}} \sin x+\frac{1}{\sqrt{2}} \cos x-1}{\frac{1}{\sqrt{2}} \sin x-\frac{1}{\sqrt{2}} \cos x} \\\\
& =\frac{\cos \left(x-\frac{\pi}{4}\right)-1}{\sin \left(x-\frac{\pi}{4}\right)} \\\\
& =\frac{-2 \sin ^2\left(\frac{x}{2}-\frac{\pi}{8}\right)}{2 \sin \left(\frac{x}{2}-\frac{\pi}{8}\right) \cos \left(\frac{x}{2}-\frac{\pi}{8}\right)}
\end{aligned}
$$
<br/><br/>$$
\begin{aligned}
& \Rightarrow f(x)=-\tan \left(\frac{x}{2}-\frac{\pi}{8}\right) \\\\
& \Rightarrow f^{\prime}(x)=-\frac{1}{2} \sec ^2\left(\frac{x}{2}-\frac{\pi}{8}\right)
\end{aligned}
$$
<br/><br/>$$
\begin{aligned}
& \Rightarrow f^{\prime \prime}(x)=-\frac{1}{2} \cdot 2 \sec \left(\frac{x}{2}-\frac{\pi}{8}\right) \cdot \sec \left(\frac{x}{2}-\frac{\pi}{8}\right)\tan \left(\frac{x}{2}-\frac{\pi}{8}\right) \times \frac{1}{2} \\\\
& =-\frac{1}{2} \sec ^2\left(\frac{x}{2}-\frac{\pi}{8}\right) \cdot \tan \left(\frac{x}{2}-\frac{\pi}{8}\right)
\end{aligned}
$$
<br/><br/>$$
\begin{aligned}
& \text { Now, } f\left(\frac{7 \pi}{12}\right) f^{\prime \prime}\left(\frac{7 \pi}{12}\right) \\\\
& =-\tan \left(\frac{7 \pi}{24}-\frac{\pi}{8}\right) \times \frac{-1}{2} \sec ^2\left(\frac{7 \pi}{24}-\frac{\pi}{8}\right) \times \tan \left(\frac{7 \pi}{24}-\frac{\pi}{8}\right) \\\\
& =\frac{1}{2} \tan ^2\left(\frac{\pi}{6}\right) \times \sec ^2 \frac{\pi}{6} \\\\
& =\frac{1}{2} \times \frac{1}{3} \times \frac{4}{3}=\frac{2}{9}
\end{aligned}
$$

