   {{{(x + a - 1)}^2} + b} &amp; {x + a \ge 0\&amp; x &lt; 0}  \cr 
   {{{(|x - 1| - 1)}^2} + b} &amp; {|x - 1| \ge 0\&amp; x \ge 0}  \cr 

 } } \right.$$<br><br>$$g[f(x)] = \left[ {\matrix{
   {x + a + 1} &amp; {x \in ( - \infty , - a)\&amp; x \in ( - \infty ,0)}  \cr 
   {|x - 1| + 1} &amp; {x \in \phi }  \cr 
   {{{(x + a - 1)}^2} + b} &amp; {x \in [ - a,\infty )\&amp; x \in [0,\infty )}  \cr 
   {{{(|x - 1| - 1)}^2} + b} &amp; {x \in R\&amp; x \in [0,\infty )}  \cr 

 } } \right.$$<br><br>$$g[f(x)] = \left[ {\matrix{
   {x + a + 1} &amp; {x \in ( - \infty , - a)}  \cr 
   {{{(x + a - 1)}^2} + b} &amp; {x \in [ - a,0)}  \cr 
   {{{(|x - 1| - 1)}^2} + b} &amp; {x \in [0,\infty )}  \cr 

 } } \right.$$<br><br>g(f(x)) is continuous.

<br><br>At x = $$-$$a
<br><br>-a + a + 1 = (-a + a - 1)<sup>2</sup> + b
<br><br>$$ \Rightarrow $$ 1 = b + 1
<br><br>$$ \Rightarrow $$ b = 0

<br><br>at x = 0
<br><br>(a $$-$$1)<sup>2</sup> + b = (|0 - 1| - 1)<sup>2</sup> + b
<br><br>$$ \Rightarrow $$ (a $$-$$1)<sup>2</sup> + b = b
<br><br>$$ \Rightarrow $$ a = 1<br><br>$$ \Rightarrow $$ a + b = 1

Given, $f(x)=\left\{\begin{array}{cl}\frac{\sin (a+1) x+\sin 2 x}{2 x}, & x<0 \\ b, & x=0 \\ \frac{\sqrt{x+b x^3}-\sqrt{x}}{b x^{5 / 2}}, & x>0\end{array}\right.$<br/><br/>
$$
\begin{array}{ll}
\because & f(x) \text { is continuous at } x=0 . \\\\
\therefore & \lim _\limits{x \rightarrow 0^{-}} f(x)=\lim _\limits{x \rightarrow 0^{+}} f(x)=f(0) \\\\
\because & f(0)=b
\end{array}
$$<br/><br/>
Now, $\lim _\limits{x \rightarrow 0^{-}} f(x)=\lim _\limits{x \rightarrow 0^{-}}\left(\frac{\sin (a+1) x+\sin 2 x}{2 x}\right)$<br/><br/>
$$
\begin{aligned}
\Rightarrow \quad \lim _\limits{x \rightarrow 0^{-}} f(x) & =\lim _\limits{x \rightarrow 0^{-}}\left(\frac{\sin (a+1) x}{2 x}+\frac{\sin 2 x}{2 x}\right) \\\\
& =\lim _\limits{x \rightarrow 0^{-}}\left(\frac{\sin (a+1) x}{(a+1) x} \times\left(\frac{a+1}{2}\right)+\frac{\sin 2 x}{2 x}\right) \\\\
& =\frac{a+1}{2}+1
\end{aligned}
$$<br/><br/>
Again, $\lim _\limits{x \rightarrow 0^{+}} f(x)=\lim _\limits{x \rightarrow 0^{+}}\left(\frac{\sqrt{x+b x^3}-\sqrt{x}}{b x^{5 / 2}}\right)$<br/><br/>
$$
=\lim _\limits{x \rightarrow 0^{+}} \frac{\left(\sqrt{x+b x^3}-\sqrt{x}\right)\left(\sqrt{x+b x^3}+\sqrt{x}\right)}{b x^{5 / 2}\left(\sqrt{x+b x^3}+\sqrt{x}\right)}
$$<br/><br/>
$$
\begin{aligned}
& =\lim _{x \rightarrow 0^{+}} \frac{\left(x+b x^3-x\right)}{b x^{5 / 2}\left(\sqrt{x+b x^3}+\sqrt{x}\right)} \\\\
& =\lim _{x \rightarrow 0^{+}} \frac{\sqrt{x}}{\sqrt{x}\left(\sqrt{1+b x^2}+1\right)}
\end{aligned}
$$<br/><br/>
$$
\Rightarrow \quad \lim _\limits{x \rightarrow 0^{+}} f(x)=1 / 2
$$<br/><br/>
From Eq. (i), (ii), (iii) and (iv)<br/><br/>
$$
\begin{aligned}
&\frac{1}{2}  =b=\frac{a+1}{2}+1 \Rightarrow b=\frac{1}{2}, a=-2 \\\\
&\therefore \quad a+b  =\frac{-3}{2}
\end{aligned}
$$

