   0 &amp; 1  \cr 

 } } \right]$$

question:
Let P = $$\left[ {\matrix{
   3 &amp; { - 1} &amp; { - 2}  \cr 
   2 &amp; 0 &amp; \alpha   \cr 
   3 &amp; { - 5} &amp; 0  \cr 

 } } \right]$$, where $$\alpha $$ $$ \in $$ R. Suppose Q = [ q<sub>ij</sub>] is a matrix satisfying PQ = kl<sub>3</sub> for some non-zero k $$ \in $$ R. <br/>If q<sub>23</sub> = $$ - {k \over 8}$$
and |Q| = $${{{k^2}} \over 2}$$, then a<sup>2</sup> + k<sup>2</sup> is equal to ______.

explanation:
As $$PQ = kI \Rightarrow Q = k{P^{ - 1}}I$$<br><br>now $$Q = {k \over {|P|}}(adjP)I $$
<br><br>$$\Rightarrow Q = {k \over {(20 + 12\alpha )}}\left[ {\matrix{
    -  &amp;  -  &amp;  -   \cr 
    -  &amp;  -  &amp; {( - 3\alpha  - 4)}  \cr 
    -  &amp;  -  &amp;  -   \cr 

 } } \right]\left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   0 &amp; 1 &amp; 0  \cr 
   0 &amp; 0 &amp; 1  \cr 

 } } \right]$$<br><br>$$ \because $$ $${q_{23}} = {{ - k} \over 8} $$
<br><br>$$\Rightarrow {k \over {(20 + 12\alpha )}}( - 3\alpha  - 4) = {{ - k} \over 8} $$
<br><br>$$\Rightarrow 2(3\alpha  + 4) = 5 + 3\alpha $$<br><br>$$3\alpha  =  - 3 \Rightarrow \alpha  =  - 1$$<br><br>also $$|Q| = {{{k^3}|I|} \over {|P|}} \Rightarrow {{{k^2}} \over 2} = {{{k^3}} \over {(20 + 12\alpha )}}$$<br><br>$$ \Rightarrow $$ $$(20 + 12\alpha ) = 2k \Rightarrow 8 = 2k \Rightarrow k = 4$$

question:
If $$A = \left[ {\matrix{
   0 &amp; { - \tan \left( {{\theta  \over 2}} \right)}  \cr 
   {\tan \left( {{\theta  \over 2}} \right)} &amp; 0  \cr 

 } } \right]$$ and <br/>$$({I_2} + A){({I_2} - A)^{ - 1}} = \left[ {\matrix{
   a &amp; { - b}  \cr 
   b &amp; a  \cr 

 } } \right]$$, then $$13({a^2} + {b^2})$$ is equal to

explanation:
$$A = \left[ {\matrix{
   0 &amp; { - \tan {\theta  \over 2}}  \cr 
   {\tan {\theta  \over 2}} &amp; 0  \cr 

 } } \right]$$<br><br>$$ \Rightarrow I + A = \left[ {\matrix{
   1 &amp; { - \tan {\theta  \over 2}}  \cr 
   {\tan {\theta  \over 2}} &amp; 1  \cr 

 } } \right]$$<br><br>$$ \Rightarrow I - A = \left[ {\matrix{
   1 &amp; {\tan {\theta  \over 2}}  \cr 
   { - \tan {\theta  \over 2}} &amp; 1  \cr 

 } } \right]$$ { $$\therefore$$ $$\left| {I - A} \right| = {\sec ^2}\theta /2$$}<br><br>$$ \Rightarrow {(I - A)^{ - 1}} = {1 \over {{{\sec }^2}{\theta  \over 2}}}\left[ {\matrix{
   1 &amp; { - \tan {\theta  \over 2}}  \cr 
   {\tan {\theta  \over 2}} &amp; 1  \cr 

 } } \right]$$<br><br>$$ \Rightarrow (1 + A){(I - A)^{ - 1}} $$

<br><br>$$= {1 \over {{{\sec }^2}{\theta  \over 2}}}\left[ {\matrix{
   1 &amp; { - \tan {\theta  \over 2}}  \cr 
   {\tan {\theta  \over 2}} &amp; 1  \cr 

 } } \right]\left[ {\matrix{
   1 &amp; { - \tan {\theta  \over 2}}  \cr 
   {\tan {\theta  \over 2}} &amp; 1  \cr 

 } } \right]$$<br><br>$$ = {1 \over {{{\sec }^2}{\theta  \over 2}}}\left[ {\matrix{
   {1 - {{\tan }^2}{\theta  \over 2}} &amp; { - 2\tan {\theta  \over 2}}  \cr 
   {2\tan {\theta  \over 2}} &amp; {1 - {{\tan }^2}{\theta  \over 2}}  \cr 

 } } \right]$$<br><br>$$a = {{1 - {{\tan }^2}{\theta  \over 2}} \over {{{\sec }^2}{\theta  \over 2}}}$$<br><br>$$b = {{2\tan {\theta  \over 2}} \over {{{\sec }^2}{\theta  \over 2}}}$$<br><br>$$\therefore$$ $${a^2} + {b^2} = 1$$
<br><br>$$ \Rightarrow $$ $$13({a^2} + {b^2})$$ = 13

question:
Let $$A = \left[ {\matrix{
   1 &amp; 2  \cr 
   { - 1} &amp; 4  \cr 

 } } \right]$$. If A<sup>$$-$$1</sup> = $$\alpha$$I + $$\beta$$A, $$\alpha$$, $$\beta$$ $$\in$$ R, I is a 2 $$\times$$ 2 identity matrix then 4($$\alpha$$ $$-$$ $$\beta$$) is equal to :

explanation:
$$A = \left[ {\matrix{
   1 &amp; 2  \cr 
   { - 1} &amp; 4  \cr 

 } } \right],|A| = 6$$<br><br>$${A^{ - 1}} = {{adjA} \over {|A|}} = {1 \over 6}\left[ {\matrix{
   4 &amp; { - 2}  \cr 
   1 &amp; 1  \cr 

 } } \right] = \left[ {\matrix{
   {{2 \over 3}} &amp; { - {1 \over 3}}  \cr 
   {{1 \over 6}} &amp; {{1 \over 6}}  \cr 

 } } \right]$$<br><br>$$\left[ {\matrix{
   {{2 \over 3}} &amp; { - {1 \over 3}}  \cr 
   {{1 \over 6}} &amp; {{1 \over 6}}  \cr 

 } } \right] = \left[ {\matrix{
   \alpha  &amp; 0  \cr 
   0 &amp; \alpha   \cr 

 } } \right] + \left[ {\matrix{
   \beta  &amp; {2\beta }  \cr 
   { - \beta } &amp; {4\beta }  \cr 

 } } \right]$$<br><br>$$\left. \matrix{
  \alpha  + \beta  = {2 \over 3} \hfill \cr 
  \beta  =  - {1 \over 6} \hfill \cr}  \right\} \Rightarrow \alpha  = {2 \over 3} + {1 \over 6} = {5 \over 6}$$<br><br>$$ \therefore $$ $$4(\alpha  - \beta ) = 4(1) = 4$$

$$
\begin{aligned}
& \mathrm{AA}^{\mathrm{T}}=\left[\begin{array}{cc}
\frac{1}{\sqrt{10}} & \frac{3}{\sqrt{10}} \\
\frac{-3}{\sqrt{10}} & \frac{1}{\sqrt{10}}
\end{array}\right]\left[\begin{array}{cc}
\frac{1}{\sqrt{10}} & \frac{-3}{\sqrt{10}} \\
\frac{3}{\sqrt{10}} & \frac{1}{\sqrt{10}}
\end{array}\right]=\left[\begin{array}{ll}
1 & 0 \\
0 & 1
\end{array}\right] = I \\\\\
& \mathrm{B}^2=\left[\begin{array}{cc}
1 & -\mathrm{i} \\
0 & 1
\end{array}\right]\left[\begin{array}{cc}
1 & -\mathrm{i} \\
0 & 1
\end{array}\right]=\left[\begin{array}{cc}
1 & -2 \mathrm{i} \\
0 & 1
\end{array}\right] \\\\
& \mathrm{B}^3=\left[\begin{array}{cc}
1 & -3 \mathrm{i} \\
0 & 1
\end{array}\right]
\end{aligned}
$$
<br/><br/>Similarly, 
<br/><br/>$$
\begin{aligned}
& \mathrm{B}^{2023}=\left[\begin{array}{cc}
1 & -2023 \mathrm{i} \\
0 & 1
\end{array}\right] \\\\
& \mathrm{M}=\mathrm{A}^{\mathrm{T}} \mathrm{BA} \\\\
& \mathrm{M}^2=\mathrm{M} \cdot \mathrm{M}=\mathrm{A}^{\mathrm{T}} \mathrm{BA} \mathrm{A}^{\mathrm{T}} \mathrm{BA}=\mathrm{A}^{\mathrm{T}} \mathrm{B}^2 \mathrm{~A} \\\\
& \mathrm{M}^3=\mathrm{M}^2 \cdot \mathrm{M}=\mathrm{A}^{\mathrm{T}} \mathrm{B}^2 \mathrm{AA}^{\mathrm{T}} \mathrm{BA}=\mathrm{A}^{\mathrm{T}} \mathrm{B}^3 \mathrm{~A}
\end{aligned}
$$
<br/><br/>Similarly,
<br/><br/>$$
\begin{aligned}
& \mathrm{M}^{2023}= \mathrm{A}^{\mathrm{T}} \mathrm{B}^{2023} \mathrm{~A} \\\\
& \mathrm{AM}^{2023} \mathrm{~A}^{\mathrm{T}}=\mathrm{AA}^{\mathrm{T}} \mathrm{B}^{2023} \mathrm{AA}^{\mathrm{T}} = \mathrm{I}.\mathrm{B}^{2023}.\mathrm{I}=\mathrm{B}^{2023} \\\\
& =\left[\begin{array}{cc}
1 & -2023 \mathrm{i} \\
0 & 1
\end{array}\right]
\end{aligned}
$$
<br/><br/>$$ \therefore $$ $$
\text { Inverse of }\left(\mathrm{AM}^{2023} \mathrm{~A}^{\mathrm{T}}\right) \text { is }\left[\begin{array}{cc}
1 & 2023 i \\
0 & 1
\end{array}\right]
$$

question:
If $$A = \left[ {\matrix{
   a &amp; b  \cr 
   b &amp; a  \cr 

 } } \right]$$ and $${A^2} = \left[ {\matrix{
   \alpha  &amp; \beta   \cr 
   \beta  &amp; \alpha   \cr 

 } } \right]$$, then

explanation:
$${A^2} = \left[ {\matrix{
   \alpha  &amp; \beta   \cr 
   \beta  &amp; \alpha   \cr 

 } } \right] = \left[ {\matrix{
   a &amp; b  \cr 
   b &amp; a  \cr 

 } } \right]\left[ {\matrix{
   a &amp; b  \cr 
   b &amp; a  \cr 

 } } \right]$$
<br><br>$$ = \left[ {\matrix{
   {{a^2} + {b^2}} &amp; {2ab}  \cr 
   {2ab} &amp; {{a^2} + {b^2}}  \cr 

 } } \right]$$
<br><br>$$\alpha  = {a^2} + {b^2};\,\,\beta  = 2ab$$

question:
Let A = $$\left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   1 &amp; 1 &amp; 0  \cr 
   1 &amp; 1 &amp; 1  \cr 

 } } \right]$$ and B = A<sup>20</sup>. Then the sum of the elements of the first column of B is :

explanation:
A = $$\left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   1 &amp; 1 &amp; 0  \cr 
   1 &amp; 1 &amp; 1  \cr 

 } } \right]$$
<br><br>A<sup>2</sup> = A.A = $$\left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   1 &amp; 1 &amp; 0  \cr 
   1 &amp; 1 &amp; 1  \cr 

 } } \right] \times \left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   1 &amp; 1 &amp; 0  \cr 
   1 &amp; 1 &amp; 1  \cr 

 } } \right]$$
<br><br>= &nbsp; $$\left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   2 &amp; 1 &amp; 0  \cr 
   3 &amp; 2 &amp; 1  \cr 

 } } \right]$$
<br><br>A<sup>3</sup> = A<sup>2</sup>.A =&nbsp; $$\left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   2 &amp; 1 &amp; 0  \cr 
   3 &amp; 2 &amp; 1  \cr 

 } } \right] \times \left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   1 &amp; 1 &amp; 0  \cr 
   1 &amp; 1 &amp; 1  \cr 

 } } \right]$$
<br><br>=  &nbsp;  $$\left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   3 &amp; 1 &amp; 0  \cr 
   6 &amp; 3 &amp; 1  \cr 

 } } \right]$$
<br><br>Similarly
<br><br>A<sup>4</sup> = &nbsp; $$\left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   4 &amp; 1 &amp; 0  \cr 
   {10} &amp; 4 &amp; 1  \cr 

 } } \right]$$
<br><br>From this we can say, 
<br><br>A<sup>n</sup> = &nbsp; $$\left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   n &amp; 1 &amp; 0  \cr 
   {{{n\left( {n + 1} \right)} \over 2}} &amp; n &amp; 1  \cr 

 } } \right]$$
<br><br>$$\therefore\,\,\,$$ A<sup>20</sup> = &nbsp; $$\left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   {20} &amp; 1 &amp; 0  \cr 
   {210} &amp; {20} &amp; 1  \cr 

 } } \right]$$
<br><br>$$\therefore\,\,\,$$ Sum of the first column 
<br><br>= 1 + 20 + 210
<br><br>= 231

question:
Let A = $$\left[ {\matrix{
   x &amp; 1  \cr 
   1 &amp; 0  \cr 

 } } \right]$$, x $$ \in $$ R and A<sup>4</sup> = [a<sub>ij</sub>].
<br/>If
a<sub>11</sub> = 109, then a<sub>22</sub> is equal to _______ .

explanation:
$${A^2} = \left[ {\matrix{
   x &amp; 1  \cr 
   1 &amp; 0  \cr 

 } } \right]\left[ {\matrix{
   x &amp; 1  \cr 
   1 &amp; 0  \cr 

 } } \right] = \left[ {\matrix{
   {{x^2} + 1} &amp; x  \cr 
   x &amp; 1  \cr 

 } } \right]$$<br><br>$${A^4} = \left[ {\matrix{
   {{x^2} + 1} &amp; x  \cr 
   x &amp; 1  \cr 

 } } \right]\left[ {\matrix{
   {{x^2} + 1} &amp; x  \cr 
   x &amp; 1  \cr 

 } } \right]$$<br><br>$$ = \left[ {\matrix{
   {{{({x^2} + 1)}^2} + {x^2}} &amp; {x({x^2} + 1) + x}  \cr 
   {x({x^2} + 1) + x} &amp; {{x^2} + 1}  \cr 

 } } \right]$$<br><br>Given $${({x^2} + 1)^2} + {x^2} = 109$$<br><br>Let $${x^2} + 1$$ = t<br><br>$${t^2} + t - 1 = 109$$<br><br>$$ \Rightarrow $$ (t $$ - $$ 10) (t + 11) = 0<br><br>$$ \therefore $$ t = 10 = x<sup>2</sup> + 1 = a<sub>22</sub>

question:
If $$A = \left[ {\matrix{
   {\cos \theta } &amp; {i\sin \theta }  \cr 
   {i\sin \theta } &amp; {\cos \theta }  \cr 

 } } \right]$$, $$\left( {\theta  = {\pi  \over {24}}} \right)$$<br/><br/>
and $${A^5} = \left[ {\matrix{
   a &amp; b  \cr 
   c &amp; d  \cr 

 } } \right]$$, where $$i = \sqrt { - 1} $$  then which one of the following is
not true?

explanation:
$$ \because $$ $$A = \left[ {\matrix{
   {\cos \theta } &amp; {i\sin \theta }  \cr 
   {i\sin \theta } &amp; {\cos \theta }  \cr 

 } } \right]$$<br><br>$$ \therefore $$ $${A^n} = \left[ {\matrix{
   {\cos \,n\theta } &amp; {i\sin \,n\theta }  \cr 
   {i\sin \,n\theta } &amp; {\cos \,n\theta }  \cr 

 } } \right],n \in N$$<br><br>$$ \therefore $$$${A^5} = \left[ {\matrix{
   {\cos \,5\theta } &amp; {i\sin \,5\theta }  \cr 
   {i\sin \,5\theta } &amp; {\cos \,5\theta }  \cr 

 } } \right] = \left[ {\matrix{
   a &amp; b  \cr 
   c &amp; d  \cr 

 } } \right]$$<br><br>$$ \therefore $$ $$a = \cos 5\theta ,\,b = i\sin 5\theta  = c,\,d = \cos 5\theta $$<br><br>$$ \therefore $$ $${a^2} - {b^2} = {\cos ^2}5\theta  + {\sin ^2}5\theta  = 1$$<br><br>$${a^2} - {c^2} = {\cos ^2}5\theta  + {\sin ^2}5\theta  = 1$$<br><br>$${a^2} - {d^2} = {\cos ^2}5\theta  - {\cos ^2}5\theta  = 1$$<br><br>$${a^2} + {b^2} = {\cos ^2}5\theta  - {\sin ^2}5\theta  = \cos 10\theta  = \cos {{10\pi } \over {24}}$$<br><br>and $$0 &lt; \cos {{5\pi } \over {12}} &lt; 1 $$
<br><br>$$\Rightarrow 0 \le {a^2} + {b^2} \le 1$$

question:
If the matrix $$A = \left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   0 &amp; 2 &amp; 0  \cr 
   3 &amp; 0 &amp; { - 1}  \cr 

 } } \right]$$ satisfies the equation<br/><br/> $${A^{20}} + \alpha {A^{19}} + \beta A = \left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   0 &amp; 4 &amp; 0  \cr 
   0 &amp; 0 &amp; 1  \cr 

 } } \right]$$ for some real numbers $$\alpha$$ and $$\beta$$, then $$\beta$$ $$-$$ $$\alpha$$ is equal to ___________.

explanation:
$${A^2} = \left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   0 &amp; 2 &amp; 0  \cr 
   3 &amp; 0 &amp; { - 1}  \cr 

 } } \right]\left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   0 &amp; 2 &amp; 0  \cr 
   3 &amp; 0 &amp; { - 1}  \cr 

 } } \right] = \left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   0 &amp; 4 &amp; 0  \cr 
   0 &amp; 0 &amp; 1  \cr 

 } } \right]$$<br><br>$${A^3} = \left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   0 &amp; 4 &amp; 0  \cr 
   0 &amp; 0 &amp; 1  \cr 

 } } \right]\left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   0 &amp; 2 &amp; 0  \cr 
   3 &amp; 0 &amp; { - 1}  \cr 

 } } \right] = \left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   0 &amp; 8 &amp; 0  \cr 
   3 &amp; 0 &amp; { - 1}  \cr 

 } } \right]$$<br><br>$${A^4} = \left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   0 &amp; 4 &amp; 0  \cr 
   0 &amp; 0 &amp; 1  \cr 

 } } \right]\left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   0 &amp; 4 &amp; 0  \cr 
   0 &amp; 0 &amp; 1  \cr 

 } } \right] = \left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   0 &amp; {16} &amp; 0  \cr 
   0 &amp; 0 &amp; 1  \cr 

 } } \right]$$<br><br>$$\eqalign{
  &amp; .  \cr 
  &amp; .  \cr 
  &amp; .  \cr 
  &amp; .  \cr 
  &amp; .  \cr 
  &amp; . \cr} $$<br><br>$${A^{19}} = \left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   0 &amp; {{2^{19}}} &amp; 0  \cr 
   3 &amp; 0 &amp; { - 1}  \cr 

 } } \right],{A^{20}} = \left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   0 &amp; {{2^{20}}} &amp; 0  \cr 
   0 &amp; 0 &amp; 1  \cr 

 } } \right]$$<br><br>$$L.H.S. = {A^{20}} + \alpha {A^{19}} + \beta A = $$
<br><br>$$\left[ {\matrix{
   {1 + \alpha  + \beta } &amp; 0 &amp; 0  \cr 
   0 &amp; {{2^{20}} + \alpha {2^{19}} + 2\beta } &amp; 0  \cr 
   {3\alpha  + 3\beta } &amp; 0 &amp; {1 - \alpha  - \beta }  \cr 

 } } \right]$$<br><br>$$R.H.S. = \left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   0 &amp; 4 &amp; 0  \cr 
   0 &amp; 0 &amp; 1  \cr 

 } } \right] $$
<br><br>$$\Rightarrow \alpha  + \beta  = 0$$ and $${2^{20}} + \alpha {2^{19}} + 2\beta  = 4$$<br><br>$$ \Rightarrow {2^{20}} + \alpha ({2^{19}} - 2) = 4$$<br><br>$$ \Rightarrow \alpha  = {{4 - {2^{20}}} \over {{2^{19}} - 2}} =  - 2$$<br><br>$$ \Rightarrow \beta  = 2$$<br><br>$$ \therefore $$ $$\beta  - \alpha  = 4$$

question:
Let $$A = \left[ {\matrix{
   a &amp; b  \cr 
   c &amp; d  \cr 

 } } \right]$$ and $$B = \left[ {\matrix{
   \alpha   \cr 
   \beta   \cr 

 } } \right] \ne \left[ {\matrix{
   0  \cr 
   0  \cr 

 } } \right]$$ such that AB = B and a + d = 2021, then the value of ad $$-$$ bc is equal to ___________.

explanation:
$$A = \left[ {\matrix{
   a &amp; b  \cr 
   c &amp; d  \cr 

 } } \right],\,B = \left[ {\matrix{
   \alpha   \cr 
   \beta   \cr 

 } } \right]$$<br><br>$$AB = B$$<br><br>$$\left[ {\matrix{
   a &amp; b  \cr 
   c &amp; d  \cr 

 } } \right]\left[ {\matrix{
   \alpha   \cr 
   \beta   \cr 

 } } \right] = \left[ {\matrix{
   \alpha   \cr 
   \beta   \cr 

 } } \right]$$<br><br>$$\left[ {\matrix{
   {a\alpha  + b\beta }  \cr 
   {c\alpha  + d\beta }  \cr 

 } } \right] = \left[ {\matrix{
   \alpha   \cr 
   \beta   \cr 

 } } \right]$$$$ \Rightarrow $$ $$\eqalign{
  &amp; a\alpha  + b\beta  = \alpha \,......(1)  \cr 
  &amp; c\alpha  + d\beta  = \beta \,......(2) \cr} $$<br><br>$$\alpha (a - 1) =  - b\beta $$ and $$c\alpha  = \beta (1 - d)$$<br><br>$${\alpha  \over \beta } = {{ - b} \over {a - 1}}$$ &amp; $${\alpha  \over \beta } = {{1 - d} \over c}$$<br><br>$$ \therefore $$ $${{ - b} \over {a - 1}} = {{1 - d} \over c}$$<br><br>$$ - bc = (a - 1)(1 - d)$$<br><br>$$ - bc = a - ad - 1 + d$$<br><br>$$ad - bc = a + d - 1$$<br><br>$$ = 2021 - 1 = 2020$$

question:
Let $$A = \left[ {\matrix{
   0 &amp; 1 &amp; 0  \cr 
   1 &amp; 0 &amp; 0  \cr 
   0 &amp; 0 &amp; 1  \cr 

 } } \right]$$. Then the number of 3 $$\times$$ 3 matrices B with entries from the set {1, 2, 3, 4, 5} and satisfying AB = BA is ____________.

explanation:
Let matrix $$B = \left[ {\matrix{
   a &amp; b &amp; c  \cr 
   d &amp; e &amp; f  \cr 
   g &amp; h &amp; i  \cr 

 } } \right]$$<br><br>$$\because$$ $$AB = BA$$<br><br>$$\left[ {\matrix{
   0 &amp; 1 &amp; 0  \cr 
   1 &amp; 0 &amp; 0  \cr 
   0 &amp; 0 &amp; 1  \cr 

 } } \right]\left[ {\matrix{
   a &amp; b &amp; c  \cr 
   d &amp; e &amp; f  \cr 
   g &amp; h &amp; i  \cr 

 } } \right] = \left[ {\matrix{
   a &amp; b &amp; c  \cr 
   d &amp; e &amp; f  \cr 
   g &amp; h &amp; i  \cr 

 } } \right]\left[ {\matrix{
   0 &amp; 1 &amp; 0  \cr 
   1 &amp; 0 &amp; 0  \cr 
   0 &amp; 0 &amp; 1  \cr 

 } } \right]$$<br><br>$$\left[ {\matrix{
   d &amp; e &amp; f  \cr 
   a &amp; b &amp; c  \cr 
   g &amp; h &amp; i  \cr 

 } } \right] = \left[ {\matrix{
   b &amp; a &amp; c  \cr 
   e &amp; d &amp; f  \cr 
   h &amp; g &amp; i  \cr 

 } } \right]$$<br><br>$$ \Rightarrow d = b,e = a,f = c,g = h$$<br><br>$$\therefore$$ Matrix $$B = \left[ {\matrix{
   a &amp; b &amp; c  \cr 
   b &amp; a &amp; c  \cr 
   g &amp; g &amp; i  \cr 

 } } \right]$$<br><br>No. of ways of selecting a, b, c, g, i<br><br>$$ = 5 \times 5 \times 5 \times 5 \times 5$$<br><br>$$ = {5^5} = 3125$$<br><br>$$\therefore$$ No. of matrices B = 3125

question:
Let $$A = \left( {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   0 &amp; 1 &amp; 1  \cr 
   1 &amp; 0 &amp; 0  \cr 

 } } \right)$$. Then A<sup>2025</sup> $$-$$ A<sup>2020</sup> is equal to :

explanation:
$$A = \left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   0 &amp; 1 &amp; 1  \cr 
   1 &amp; 0 &amp; 0  \cr 

 } } \right] \Rightarrow {A^2} = \left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   1 &amp; 1 &amp; 1  \cr 
   1 &amp; 0 &amp; 0  \cr 

 } } \right]$$<br><br>$${A^3} = \left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   2 &amp; 1 &amp; 1  \cr 
   1 &amp; 0 &amp; 0  \cr 

 } } \right] \Rightarrow {A^4} = \left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   3 &amp; 1 &amp; 1  \cr 
   1 &amp; 0 &amp; 0  \cr 

 } } \right]$$<br><br>$${A^n} = \left[ {\matrix{
   1 &amp; 0 &amp; 0  \cr 
   {n - 1} &amp; 1 &amp; 1  \cr 
   1 &amp; 0 &amp; 0  \cr 

 } } \right]$$<br><br>$${A^{2025}} - {A^{2020}} = \left[ {\matrix{
   0 &amp; 0 &amp; 0  \cr 
   5 &amp; 0 &amp; 0  \cr 
   0 &amp; 0 &amp; 0  \cr 

 } } \right]$$<br><br>$${A^6} - A = \left[ {\matrix{
   0 &amp; 0 &amp; 0  \cr 
   5 &amp; 0 &amp; 0  \cr 
   0 &amp; 0 &amp; 0  \cr 

 } } \right]$$

$$A = {1 \over 2}\left[ {\matrix{
   1 & {\sqrt 3 }  \cr 
   { - \sqrt 3 } & 1  \cr 

 } } \right]$$
<br/><br/>Let $\theta=\frac{\pi}{3}$
<br/><br/>$$
\begin{aligned}
A^2 & =\left[\begin{array}{cc}
\cos \theta & \sin \theta \\\\
-\sin \theta & \cos \theta
\end{array}\right]\left[\begin{array}{cc}
\cos \theta & \sin \theta \\\\
-\sin \theta & \cos \theta
\end{array}\right] \\\\
& =\left[\begin{array}{cc}
\cos 2 \theta & \sin 2 \theta \\\\
-\sin 2 \theta & \cos 2 \theta
\end{array}\right] \\\\
A^3 & =\left[\begin{array}{cc}
\cos 2 \theta & \sin 2 \theta \\\\
-\sin 2 \theta & \cos 2 \theta
\end{array}\right]\left[\begin{array}{cc}
\cos \theta & \sin \theta \\\\
-\sin \theta & \cos \theta
\end{array}\right] \\\\
& =\left[\begin{array}{cc}
\cos 3 \theta & \sin 3 \theta \\\\
-\sin 3 \theta & \cos 3 \theta
\end{array}\right]
\end{aligned}
$$
<br/><br/>$\begin{aligned} & \therefore \quad A^{30}=\left[\begin{array}{cc}\cos 30 \theta & \sin 30 \theta \\\\ -\sin 30 \theta & \cos 30 \theta\end{array}\right]=\left[\begin{array}{ll}1 & 0 \\ 0 & 1\end{array}\right] \\\\ & A^{25}=\left[\begin{array}{cc}\cos 25 \theta & \sin 25 \theta \\\\ -\sin 25 \theta & \cos 25 \theta\end{array}\right]=\frac{1}{2}\left[\begin{array}{cc}1 & \sqrt{3} \\ -\sqrt{3} & 1\end{array}\right]=A \\\\ & \therefore \quad A^{30}+A^{25}-A=I\end{aligned}$

